function settings(query, channel, timestamp) {
  const keyword = query.trim();
  if (
    !keyword ||
    keyword === "@YOUR_X_HANDLE" ||
    keyword.length > 512 ||
    !/^[CG][A-Z0-9]{8,}$/.test(channel)
  ) {
    throw new Error("Set the X search query and a Slack channel ID");
  }
  const time = typeof timestamp === "string" ? Date.parse(timestamp) : NaN;
  if (!Number.isFinite(time)) throw new Error("The schedule did not provide a valid timestamp");
  const end = Math.floor(time / 600000) * 600000;
  return { keyword, channel, start: end - 600000, end };
}

const config = settings("@YOUR_X_HANDLE", "YOUR_SLACK_CHANNEL_ID", $input.first().json.timestamp);
return [
  {
    json: {
      ...config,
      startTime: new Date(config.start).toISOString(),
      endTime: new Date(config.end + 1000).toISOString(),
    },
  },
];

function postRecord(id, date) {
  const time = typeof date === "string" ? Date.parse(date) : NaN;
  if (typeof id !== "string" || !/^[1-9]\d{0,18}$/.test(id) || !Number.isFinite(time)) {
    throw new Error("X returned a post without an exact string ID and creation time");
  }
  return { id, time };
}

function includeRecent(previous, rows, limits) {
  const recent = new Map(previous.map((row) => [row.id, row]));
  for (const row of rows) {
    if (row.time <= limits.start || row.time > limits.end) continue;
    const earlier = recent.get(row.id);
    if (earlier && earlier.time !== row.time)
      throw new Error("X returned inconsistent creation times for the same post");
    recent.set(row.id, row);
  }
  return [...recent.values()]
    .sort((a, b) => b.time - a.time || b.id.length - a.id.length || b.id.localeCompare(a.id))
    .slice(0, 50);
}

function slackText(id) {
  return "New mention on X\nhttps://x.com/i/web/status/" + id;
}

const config = $("Set X query and Slack channel").first().json;
const body = $input.first().json;
if (
  !Number.isInteger(body.meta?.result_count) ||
  body.errors?.length ||
  (body.data !== undefined && !Array.isArray(body.data)) ||
  (body.data?.length ?? 0) !== body.meta.result_count
) {
  throw new Error("X did not return a complete recent search response");
}
return includeRecent(
  [],
  (body.data ?? []).map((post) => postRecord(post.id, post.created_at)),
  config,
).map(({ id }) => ({ json: { id, channel: config.channel, text: slackText(id) } }));

function checkSlack(receipt, channel) {
  if (receipt.channel !== channel || !/^\d+\.\d+$/.test(receipt.ts ?? "")) {
    throw new Error("Slack did not confirm the message. Check the channel before replaying.");
  }
}

const { id, channel } = $("Take one mention").item.json;
if ($json.ok !== true) throw new Error("Slack rejected the message");
const ts = $json.message_timestamp;
checkSlack({ channel: $json.channel, ts }, channel);
return { json: { id, ts } };
